What will be the output of the following code snippet?

```c
#include <stdio.h>
int main() {
int a = 3, b = 5;
int t = a;
a = b;
b = t;
printf("%d %d", a, b);
return 0;
}
```

What is the output of the following code snippet?

```c
int main() {
int sum = 2 + 4 / 2 + 6 * 2;
printf("%d", sum);
return 0;
}
```

What will be the output of the following code snippet?

```c
#include <stdio.h>
int main() {
int a = 3;
int res = a++ + ++a + a++ + ++a;
printf("%d", res);
}
```

What will be the output of the following code snippet?

```c
void solve() {
printf("%d ", 9 / 2);
printf("%f", 9.0 / 2);
}
```

